// Precompute the first 512 points at compile time. This preserves every bit of
// the direction-number calculation and avoids a variable popcount loop per ray
// dimension. Larger sample indices use the original calculation.
constexpr auto make_sobol_points(){
 std::array<std::array<unsigned,32>,512> points{};
 for(unsigned k=1;k<512;k++){
  unsigned bit=0,n=k;while(!(n&1)){++bit;n>>=1;}
  for(unsigned d=0;d<32;d++)points[k][d]=points[k-1][d]^sobol_directions[d][bit];
 }
 return points;
}
static constexpr auto sobol_points=make_sobol_points();
